{
  "mechanisms": [
    {
      "name": "baseline_initialization",
      "title": "Baseline Q-value Initialization",
      "description": "Initializes model-free Q-values for both stages to a parameterized baseline value.",
      "params": [
        {
          "name": "center",
          "bounds": [0, 1]
        }
      ],
      "evidence": "q_stage1_mf = np.full(2, float(center))\n    q_stage2_mf = np.full((2, 2), float(center))",
      "expressible_in_slots": true
    },
    {
      "name": "mb_mf_mixture",
      "title": "Model-Based / Model-Free Mixture",
      "description": "Computes stage 1 values as a weighted average of model-based and model-free Q-values.",
      "params": [
        {
          "name": "w",
          "bounds": [0, 1]
        }
      ],
      "evidence": "q_net = w * q_stage1_mb + (1 - w) * q_stage1_mf",
      "expressible_in_slots": true
    },
    {
      "name": "stage_1_perseveration",
      "title": "Stage 1 Perseveration",
      "description": "Adds a bonus to the stage 1 logits for repeating the previous trial's stage 1 choice.",
      "params": [
        {
          "name": "pi1",
          "bounds": [-5, 5]
        }
      ],
      "evidence": "pers1 = np.zeros(2)\n        if last_action_1 != -1:\n            pers1[last_action_1] = 1\n            \n        logits_1 = beta * q_net + pi1 * pers1",
      "expressible_in_slots": true
    },
    {
      "name": "stage_2_perseveration",
      "title": "Stage 2 Perseveration",
      "description": "Adds a bonus to the stage 2 logits for repeating the previous trial's stage 2 choice in the same state.",
      "params": [
        {
          "name": "pi2",
          "bounds": [-5, 5]
        }
      ],
      "evidence": "pers2 = np.zeros(2)\n        if last_action_2[state_idx] != -1:\n            pers2[last_action_2[state_idx]] = 1\n\n        logits_2 = beta * q_stage2_mf[state_idx] + pi2 * pers2",
      "expressible_in_slots": true
    },
    {
      "name": "value_decay_to_baseline",
      "title": "Value Decay to Baseline",
      "description": "Decays all model-free Q-values towards a parameterized baseline center before TD updates.",
      "params": [
        {
          "name": "decay",
          "bounds": [0, 1]
        },
        {
          "name": "center",
          "bounds": [0, 1]
        }
      ],
      "evidence": "q_stage1_mf += decay * (center - q_stage1_mf)\n        q_stage2_mf += decay * (center - q_stage2_mf)",
      "expressible_in_slots": true
    },
    {
      "name": "eligibility_trace",
      "title": "Eligibility Trace",
      "description": "Updates the stage 1 model-free Q-value using the stage 2 reward prediction error scaled by an eligibility trace parameter.",
      "params": [
        {
          "name": "lambda_",
          "bounds": [0, 1]
        }
      ],
      "evidence": "q_stage1_mf[action_1[trial]] += alpha * lambda_ * delta_stage2",
      "expressible_in_slots": true
    }
  ]
}
